<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';import {login} from '../stores/auth';import {useTask} from '../hooks/useTask';import Notice from '../components/common/Notice.vue';const email=ref('analyst@chengchuan.demo'),password=ref('Pipe2026!'),router=useRouter();const {busy,error,execute}=useTask();function submit(){execute(async()=>{await login(email.value,password.value);router.push('/')})}</script><template><div class="login-screen"><section class="login-story"><div class="eyebrow">CHENGCHUAN WATER / NORTH OPERATIONS</div><div class="large-mark">川</div><h1>让每一次巡检，<br>更接近问题。</h1><p>从 620 段管网的观测出发，<br>把漏损风险转化为有依据的现场优先级。</p><div class="login-caption">分层验证 / 成本阈值 / 现场复核</div></section><section class="login-panel"><div class="eyebrow">巡检推演室 · 访问验证</div><h2>进入工作台</h2><p>城北运维队 · 数据分析与审批协作</p><form @submit.prevent="submit"><label>工作账号<input v-model="email" type="email" required autocomplete="username"></label><label>密码<input v-model="password" type="password" required autocomplete="current-password"></label><Notice :error="error"/><button class="primary" :disabled="busy">{{busy?'正在验证…':'登录工作台 →'}}</button></form><div class="demo-accounts"><span>演示账号 · 密码均为 Pipe2026!</span><button v-for="r in ['analyst','admin','viewer']" :key="r" class="text-button" @click="email=r+'@chengchuan.demo'">{{r}}</button></div><small class="muted">本环境使用模拟数据，仅供巡检分析流程演示。</small></section></div></template>
